CREATE OR REPLACE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `Quarterly Orders` AS select distinct `Customers`.`CustomerID` AS `CustomerID`,`Customers`.`CompanyName` AS `CompanyName`,`Customers`.`City` AS `City`,`Customers`.`Country` AS `Country` from (`Orders` left join `Customers` on(`Customers`.`CustomerID` = `Orders`.`CustomerID`)) where `Orders`.`OrderDate` between '1997-01-01' and '1997-12-31';
